function fillBatch(){if(!batchSnapshot)return;const s=batchSnapshot.settings;$('batchPolicy').value=s.policy;$('batchValidation').value=s.split.validation_bps/100;$('batchTest').value=s.split.test_bps/100;$('batchSalt').value=s.split.salt;for(const key of batchLimitKeys)$('batch_'+key).value=s.limits[key]??'';batchChosen=new Set(batchSnapshot.files);}
function acceptBatch(s){if(batchSnapshot&&s.revision<batchSnapshot.revision)return;const sync=!batchSnapshot||batchPending||!batchDirty;if(s.rollout_running&&s.rollout_partition)$('rolloutPartition').value=s.rollout_partition;const newCollection=s.collection?.file!==batchSnapshot?.collection?.file;if((newCollection&&s.collection)||s.collection_running){const c=s.collection_running?s.collection_config:s.collection.report.config;if(c){$('collectionSeed').value=c.start_seed;$('collectionCount').value=c.count;$('collectionHorizon').value=c.horizon;$('collectionSeconds').value=c.max_seconds;}}if(newCollection&&!s.busy&&api)refreshEpisodeFiles().catch(()=>{});const newCampaign=s.campaign?.file!==batchSnapshot?.campaign?.file;if(newCampaign&&s.campaign){campaignChosen=new Set(s.campaign.report.config.policies);$('campaignSeconds').value=s.campaign.report.config.max_seconds;}if(s.campaign_running&&s.campaign_config){campaignChosen=new Set(s.campaign_config.policies);$('campaignSeconds').value=s.campaign_config.max_seconds;}const newRollout=s.rollout?.directory!==batchSnapshot?.rollout?.directory;const newJob=s.training?.directory!==batchSnapshot?.training?.directory;batchSnapshot=s;if(newRollout&&!s.busy&&s.rollout?.result.split)$('rolloutPartition').value=s.rollout.result.split;if(newJob&&s.training?.result.config){$('trainingSteps').value=s.training.result.config.max_steps;$('trainingSeconds').value=s.training.result.config.max_seconds;}if(newJob&&!s.busy&&api)refreshTrainingJobs().catch(()=>{});if(newRollout&&!s.busy&&api)refreshRolloutJobs().catch(()=>{});if(newCampaign&&!s.busy&&api)refreshCampaignFiles().catch(()=>{});if(sync){fillBatch();batchDirty=false;}batchPending=false;renderBatch();}
function renderBatchFiles(){
 const focused=$('batchFiles').contains(document.activeElement)?document.activeElement.getAttribute('aria-label'):null;
 const names=[...new Set([...batchCatalog,...batchChosen])].sort();
 $('batchFiles').replaceChildren(...names.map(name=>{const row=document.createElement('label'),input=document.createElement('input'),text=document.createElement('span');input.type='checkbox';input.checked=batchChosen.has(name);input.disabled=!!batchSnapshot?.busy;input.setAttribute('aria-label',name);text.textContent=name;input.onchange=()=>{if(input.checked)batchChosen.add(name);else batchChosen.delete(name);markBatchDirty();};row.append(input,text);return row;}));
 if(!names.length)$('batchFiles').textContent=t('batch_empty');if(focused)[...$('batchFiles').querySelectorAll('input')].find(el=>el.getAttribute('aria-label')===focused)?.focus({preventScroll:true});$('batchCount').textContent=`${batchChosen.size}/64`;
}
